pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;

    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipientSeed, uint256 rewardAmount) public {
        uint256 amt = bound(rewardAmount, 0, 1 ether);

        Reverter reverter = new Reverter();
        address attacker = address(reverter);

        vm.deal(address(c), 1 ether);

        address recipient = recipientSeed;
        vm.assume(recipient != address(0));

        vm.deal(recipient, 1 wei);

        bool ok1;
        try c.withdrawReward(recipient) {
            ok1 = true;
        } catch {
            ok1 = false;
        }

        bool ok2;
        try c.withdrawReward(recipient) {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(ok1 && ok2);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
}
